// Collisions with the physics library (code_physics): of a mesh with many triangles, the library tells which are near the path of the
// mover, and only those are tested by the runtime, with the same tests and in the same order as when it looks at all of them. So what
// collides, and how, does not change; only how many triangles are looked at.

#include <math.h>
#include <stdint.h>
#include <string.h>
#include <vector>

#include "collision_internal.hpp"
#include "environment.h"
#include "physics_library.hpp"
#include "scene_internal.hpp"

namespace bb::collision {
namespace {
	constexpr uint32_t min_triangles = 64; // Fewer are tested faster one by one than by asking the library.

	struct cache {
		bp_mesh*    mesh = nullptr;
		uint64_t    geometry = 0;
		uint32_t    checked = 0; // The surface_epoch at which the mesh was last known to be current.
		uint16_t    rebuilds = 0;
		bool        usable = false; // Whether the entity is a mesh for the library, as of the geometry.
		bool        churn = false;  // Its triangles change all the time, so the runtime always looks at all of them.
		buffer<int> first_triangle;
	};

	physics::api const* lib = nullptr;
	buffer<cache*>      caches; // By entity number - 1.
	bool                tried = false, enabled = false;
	std::vector<uint32_t> found;

	void drop(cache& c)
	{
		if (c.mesh) {
			lib->mesh_destroy(c.mesh);
			c.mesh = nullptr;
		}
		c.first_triangle.clear();
	}

	// Makes the mesh current. False if the entity is not for the library.
	bool refresh(entity& e, cache& c)
	{
		if (c.churn) {
			return false;
		}
		if (c.checked == surface_epoch) {
			return c.mesh != nullptr;
		}
		c.checked = surface_epoch;
		uint64_t geometry = physics_mesh_geometry(e);
		if ((geometry == c.geometry) && (c.mesh || !c.usable)) {
			return c.mesh != nullptr;
		}
		// Its triangles are new.
		bool changed = (c.geometry != 0);
		c.geometry   = geometry;
		drop(c);
		c.usable = physics_mesh_usable(e, min_triangles);
		if (!c.usable) {
			return false;
		}
		if (changed && (++c.rebuilds > 16)) {
			c.churn = true;
			return false;
		}
		c.mesh = physics_mesh_build(*lib, e, c.first_triangle);
		if (!c.mesh) {
			c.usable = false;
		}
		return c.mesh != nullptr;
	}
} // namespace

bool collision_triangles(int handle, entity& e, const float* m, box3 const& area, buffer<candidate_triangle>& out)
{
	if (!tried) {
		tried = true;
		const char* backend = bb_env("BLITZLLVM_COLLISION_BACKEND");
		if (!backend || ((strcmp(backend, "legacy") != 0) && (strcmp(backend, "0") != 0))) {
			lib     = physics::library();
			enabled = lib != nullptr;
		}
	}
	if (!enabled || (e.surfaces.size == 0) || area.empty) {
		return false;
	}
	while (caches.size < uint32_t(handle)) {
		caches.push(nullptr);
	}
	cache*& c = caches[uint32_t(handle) - 1];
	if (!c) {
		c = new cache();
	}
	if (!refresh(e, *c)) {
		return false;
	}
	// The box in the space of the mesh, a little larger as the tests of the runtime have an epsilon of their own.
	float inverse[16];
	mat_affine_inverse(m, inverse);
	box3 local;
	for (int corner = 0; corner < 8; corner++) {
		local.add(transform(inverse, { (corner & 1) ? area.hi.x : area.lo.x, (corner & 2) ? area.hi.y : area.lo.y, (corner & 4) ? area.hi.z : area.lo.z }));
	}
	float shortest = fminf(length({ m[0], m[1], m[2] }), fminf(length({ m[4], m[5], m[6] }), length({ m[8], m[9], m[10] })));
	if (!(shortest > 1e-6f) || !isfinite(shortest)) {
		return false;
	}
	float size = 0;
	for (float v : { local.lo.x, local.lo.y, local.lo.z, local.hi.x, local.hi.y, local.hi.z }) {
		size = fmaxf(size, fabsf(v));
	}
	float pad = (4 * collision_epsilon) / shortest + 1e-4f * size;
	if (!isfinite(pad) || !isfinite(size)) {
		return false;
	}
	float lo[3] = { local.lo.x - pad, local.lo.y - pad, local.lo.z - pad }, hi[3] = { local.hi.x + pad, local.hi.y + pad, local.hi.z + pad };
	if (found.size() < 4096) {
		found.resize(4096);
	}
	uint32_t count = lib->mesh_query_box(c->mesh, lo, hi, found.data(), uint32_t(found.size()));
	if (count > found.size()) {
		found.resize(count);
		count = lib->mesh_query_box(c->mesh, lo, hi, found.data(), uint32_t(found.size()));
	}
	out.clear();
	uint32_t surface = 0;
	for (uint32_t k = 0; k < count; k++) {
		while ((surface + 1 < c->first_triangle.size) && (int(found[k]) >= c->first_triangle[surface + 1])) {
			surface++;
		}
		out.push({ surface, found[k] - uint32_t(c->first_triangle[surface]) });
	}
	return true;
}
} // namespace bb::collision
